def f(inp, mode='right'):
    W=len(inp[0]); ap=[j for j,x in enumerate(inp[0]) if x==2][0]
    o=[[inp[0][j] for j in range(W)] for _ in range(W)]
    for r in range(1,W):
        for j in range(W):
            if abs(j-ap)==r: continue
            inside = ap-r<j<ap+r
            leftside = j<ap-r  # strictly left of the arm? no
            # left arm boundary: j <= ap-r -> cells at or beyond left arm
            if j<=ap-r or j>=ap+r: continue   # outside both arms
            if (r+j)%4==(ap+2)%4 and r+j>=ap+2: o[r][j]=1
            elif (r-j)%4==(-ap)%4 and r+j>=ap+2: o[r][j]=1
    return o
for mode in ['left','right','both']:
    def _(inp):
        W=len(inp[0]); ap=[j for j,x in enumerate(inp[0]) if x==2][0]
        o=[[inp[0][j] for j in range(W)] for _ in range(W)]
        for r in range(1,W):
            for j in range(W):
                if abs(j-ap)==r: continue
                if (j<=ap-r or j>=ap+r): continue
                n = (mode=='left' and (r-j)%4==(-ap)%4) or (mode=='right' and (r+j)%4==(ap+2)%4) or ((r-j)%4==(-ap)%4 and (r+j)%4==(ap+2)%4)
                if n and r+j>=ap+2: o[r][j]=1
        return o
    for m in ['left','right','both']:
        print('demo check', m)
        for name in ['Demo pair 1','Demo pair 2','Demo pair 3']:
            p=_(G[name+' input']); e=G[name+' output']
